import { Injectable, signal } from '@angular/core';

export type SgTheme = 'light' | 'dark';
/** Từ vựng density chuẩn theo Astryx (khớp HrmGridDensity của hrm-grid). */
export type SgDensity = 'compact' | 'balanced' | 'spacious';
export type SgNeutral = 'slate' | 'gray';
export type SgFont = 'roboto' | 'inter' | 'bevietnam' | 'sfpro';
export type SgRadius = 'sharp' | 'default' | 'rounded';
/** Cỡ chữ toàn hệ thống (chỉ scale CHỮ — khoảng cách do density, bo góc do radius). */
export type SgFontSize = 'sm' | 'default' | 'lg';

/** Radius preset → hệ số nhân --radius-scale (áp cả thang radius). */
export const RADIUS_SCALE: Record<SgRadius, number> = {
  sharp: 0.5,
  default: 1,
  rounded: 1.6,
};

/** Font size preset → hệ số nhân --font-scale (áp cả thang --fs-* + --text-*-font-size).
 *  Giữ biên độ vừa phải để chữ lớn không vỡ nút/hàng có chiều cao cố định. */
export const FONT_SIZE_SCALE: Record<SgFontSize, number> = {
  sm: 0.875,
  default: 1,
  lg: 1.125,
};

/** Preset brand color — đổi --primary-base, các token primary phái sinh (hover,
 *  bg-subtle, border, focus-ring, alpha) tự lan qua color-mix. */
export interface BrandPreset { key: string; hex: string; }
export const BRAND_PRESETS: BrandPreset[] = [
  { key: 'blue', hex: '#2267E8' },   // default ship
  { key: 'indigo', hex: '#4F46E5' },
  { key: 'teal', hex: '#0D9488' },
  { key: 'green', hex: '#16A34A' },
  { key: 'rose', hex: '#E11D48' },
  { key: 'orange', hex: '#EA580C' },
  { key: 'slate', hex: '#475569' },
];

export const FONT_OPTIONS: { key: SgFont; label: string }[] = [
  { key: 'roboto', label: 'Roboto' },
  { key: 'inter', label: 'Inter' },
  { key: 'bevietnam', label: 'Be Vietnam Pro' },
  { key: 'sfpro', label: 'SF Pro' },
];

/** Giá trị gốc của token --primary-base trong CSS (remove property = quay về màu này). */
const TOKEN_BRAND = '#2267E8';
/** Mặc định khi vào site lần đầu (chưa có lựa chọn lưu): brand xanh lá + dark. */
const DEFAULT_BRAND = '#16A34A';
const DEFAULT_THEME: SgTheme = 'dark';

/** Điều khiển theme + density + brand + neutral + font cho styleguide (persist).
 *  Áp bằng cách set CSS var / attribute lên <html>, token phái sinh tự lan. */
@Injectable({ providedIn: 'root' })
export class SgThemeService {
  readonly theme = signal<SgTheme>(this.readTheme());
  readonly density = signal<SgDensity>(this.readDensity());
  readonly brand = signal<string>(this.read('sg.brand') || DEFAULT_BRAND);
  readonly neutral = signal<SgNeutral>(this.read('sg.neutral') === 'gray' ? 'gray' : 'slate');
  readonly font = signal<SgFont>(this.readFont());
  readonly radius = signal<SgRadius>(this.readRadius());
  readonly fontSize = signal<SgFontSize>(this.readFontSize());
  /** Hiệu ứng vệt chất lỏng bám con trỏ (demo site) — mặc định TẮT (chỉ bật khi Config lưu 'on'). */
  readonly cursorFx = signal<boolean>(this.read('sg.cursorFx') === 'on');

  constructor() {
    this.applyTheme(this.theme());
    this.applyDensity(this.density());
    this.applyBrand(this.brand());
    this.applyNeutral(this.neutral());
    this.applyFont(this.font());
    this.applyRadius(this.radius());
    this.applyFontSize(this.fontSize());
  }

  setTheme(t: SgTheme): void { this.theme.set(t); this.applyTheme(t); this.save('sg.theme', t); }
  toggleTheme(): void { this.setTheme(this.theme() === 'dark' ? 'light' : 'dark'); }

  /** Đổi theme kèm hiệu ứng vòng tròn thu phóng (View Transitions API), tâm = điểm bấm (x,y).
   *  Trình duyệt không hỗ trợ hoặc user giảm chuyển động → đổi thẳng, không animation. */
  setThemeAnimated(t: SgTheme, x?: number, y?: number): void {
    const doc = document as Document & { startViewTransition?: (cb: () => void) => { ready: Promise<void> } };
    const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
    if (!doc.startViewTransition || reduce || t === this.theme()) { this.setTheme(t); return; }
    const cx = x ?? window.innerWidth - 40;
    const cy = y ?? 24;
    const r = Math.hypot(Math.max(cx, window.innerWidth - cx), Math.max(cy, window.innerHeight - cy));
    const vt = doc.startViewTransition(() => this.setTheme(t));
    vt.ready.then(() => {
      document.documentElement.animate(
        { clipPath: [`circle(0px at ${cx}px ${cy}px)`, `circle(${r}px at ${cx}px ${cy}px)`] },
        { duration: 560, easing: 'cubic-bezier(.22,.61,.36,1)', pseudoElement: '::view-transition-new(root)' },
      );
    }).catch(() => { /* ignore */ });
  }
  setDensity(d: SgDensity): void { this.density.set(d); this.applyDensity(d); this.save('sg.density', d); }
  setCursorFx(on: boolean): void { this.cursorFx.set(on); this.save('sg.cursorFx', on ? 'on' : 'off'); }
  setBrand(hex: string): void { this.brand.set(hex); this.applyBrand(hex); this.save('sg.brand', hex); }
  setNeutral(n: SgNeutral): void { this.neutral.set(n); this.applyNeutral(n); this.save('sg.neutral', n); }
  setFont(f: SgFont): void { this.font.set(f); this.applyFont(f); this.save('sg.font', f); }
  setRadius(r: SgRadius): void { this.radius.set(r); this.applyRadius(r); this.save('sg.radius', r); }
  setFontSize(s: SgFontSize): void { this.fontSize.set(s); this.applyFontSize(s); this.save('sg.fontSize', s); }

  private applyTheme(t: SgTheme): void {
    document.documentElement.classList.toggle('dark', t === 'dark');
  }
  private applyDensity(d: SgDensity): void {
    document.documentElement.setAttribute('data-density', d);
  }
  private applyBrand(hex: string): void {
    const root = document.documentElement;
    if (hex.toUpperCase() === TOKEN_BRAND) root.style.removeProperty('--primary-base');
    else root.style.setProperty('--primary-base', hex);
  }
  private applyNeutral(n: SgNeutral): void {
    document.documentElement.setAttribute('data-neutral', n);
  }
  private applyFont(f: SgFont): void {
    document.documentElement.style.setProperty('--font-sans', `var(--font-${f})`);
  }
  private applyRadius(r: SgRadius): void {
    const root = document.documentElement;
    if (r === 'default') root.style.removeProperty('--radius-scale');
    else root.style.setProperty('--radius-scale', String(RADIUS_SCALE[r]));
  }
  private applyFontSize(s: SgFontSize): void {
    const root = document.documentElement;
    if (s === 'default') root.style.removeProperty('--font-scale');
    else root.style.setProperty('--font-scale', String(FONT_SIZE_SCALE[s]));
  }

  private readTheme(): SgTheme {
    const v = this.read('sg.theme');
    return v === 'light' || v === 'dark' ? v : DEFAULT_THEME;
  }
  private readDensity(): SgDensity {
    const v = this.read('sg.density');
    // migrate giá trị cũ: standard→balanced, comfortable→spacious
    if (v === 'comfortable' || v === 'spacious') return 'spacious';
    return v === 'compact' ? 'compact' : 'balanced';
  }
  private readFont(): SgFont {
    const v = this.read('sg.font');
    return v === 'inter' || v === 'bevietnam' || v === 'sfpro' ? v : 'roboto';
  }
  private readRadius(): SgRadius {
    const v = this.read('sg.radius');
    return v === 'sharp' || v === 'rounded' ? v : 'default';
  }
  private readFontSize(): SgFontSize {
    const v = this.read('sg.fontSize');
    return v === 'sm' || v === 'lg' ? v : 'default';
  }

  private read(key: string): string | null {
    try { return localStorage.getItem(key); } catch { return null; }
  }
  private save(key: string, val: string): void {
    try { localStorage.setItem(key, val); } catch { /* ignore */ }
  }
}
